#!/usr/bin/env node
import { readFile, readdir, mkdir, writeFile, stat } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { MaxRectsPacker } from 'maxrects-packer';
import { createHash } from 'node:crypto';
import textureSizeOf from 'buffer-image-size';
import sharp from 'sharp';
import { object, optional, number, union, literal, string, array, record, boolean, parse } from 'valibot';

const DEFAULT_HASHING_ALGORITHM = 'sha256';
//algorithm
class Assets {
    cwd;
    bufferCache = new Map();
    textureDataCache = new Map();
    hashDataCache = new Map();
    constructor(cwd) {
        this.cwd = cwd;
    }
    async readFile(filePath) {
        const currentFilePath = path.resolve(this.cwd, filePath);
        const cachedBuffer = this.bufferCache.get(currentFilePath);
        if (cachedBuffer)
            return cachedBuffer;
        const buffer = await readFile(currentFilePath);
        this.bufferCache.set(currentFilePath, buffer);
        return buffer;
    }
    async getTextureData(filepath, withoutExtension = false) {
        const buffer = await this.readFile(filepath);
        const cachedTextureData = this.textureDataCache.get(buffer);
        if (cachedTextureData)
            return cachedTextureData;
        const { width, height, type } = textureSizeOf(buffer);
        const name = withoutExtension ? path.basename(filepath, path.extname(filepath)) : path.basename(filepath);
        const textureData = {
            filepath,
            name,
            type,
            buffer,
            sourceWidth: width,
            sourceHeight: height,
            x: 0,
            y: 0,
            rot: false,
            width: width,
            height: height,
            offsetTop: 0,
            offsetLeft: 0,
            trimmed: false,
            hash: await this.getFileHash(buffer),
        };
        this.textureDataCache.set(buffer, textureData);
        return textureData;
    }
    async getFileHash(data, algorithm = DEFAULT_HASHING_ALGORITHM) {
        const currentBuffer = typeof data === 'string' ? await this.readFile(data) : data;
        const hash = createHash(algorithm);
        const hex = hash.update(currentBuffer).digest('hex');
        this.hashDataCache.set(currentBuffer, hex);
        return hex;
    }
}

const DEFAULT_SPRITESHEETS_FORMAT = 'RGBA8888';
const DEFAULT_SPRITE_BG_OPTIONS = { alpha: 0, r: 0, g: 0, b: 0 };
const SPRITE_ALPHA_CHANNELS = 4;
const DEFAULT_SPRITESHEETS_NAME = 'sprite';
const DEFAULT_ASSET_CACHE_NAME = '.assets-cache';

async function resizeTexture(textureData, scale = 1) {
    const width = Math.round(textureData.width * scale);
    const height = Math.round(textureData.height * scale);
    const buffer = await sharp(textureData.buffer).resize(width, height).toBuffer();
    return { ...textureData, buffer, width, height, sourceWidth: width, sourceHeight: height };
}
async function trimTexture(textureData) {
    const { data, info } = await sharp(textureData.buffer).trim().toBuffer({ resolveWithObject: true });
    if (!info.trimOffsetLeft || !info.trimOffsetTop)
        return textureData;
    return {
        ...textureData,
        trimmed: true,
        width: info.width,
        height: info.height,
        offsetLeft: -info.trimOffsetLeft,
        offsetTop: -info.trimOffsetTop,
        buffer: data,
    };
}
async function rotateTexture(textureData, rotate = 90) {
    const buffer = await sharp(textureData.buffer).rotate(rotate).toBuffer();
    return { ...textureData, buffer, rot: true };
}

function createOverlayOptions(textureDataList) {
    return textureDataList.map(({ buffer, x, y }) => {
        return {
            input: buffer,
            left: x,
            top: y,
        };
    });
}
function createSpriteFactory(width, height, options) {
    const background = options?.background || DEFAULT_SPRITE_BG_OPTIONS;
    return sharp({ create: { width, height, background, channels: SPRITE_ALPHA_CHANNELS } });
}
function createSpritesheetsFrames(textureDataList) {
    return textureDataList.reduce((acc, textureData) => {
        const { name, sourceWidth, sourceHeight, x, y, rot, trimmed, width, height, offsetTop, offsetLeft } = textureData;
        const size = { w: width, h: height };
        acc[name] = {
            frame: { x, y, ...size },
            spriteSourceSize: { x: offsetLeft, y: offsetTop, ...size },
            sourceSize: { w: sourceWidth, h: sourceHeight },
            rotated: rot,
            trimmed,
        };
        return acc;
    }, {});
}
function createSpritesheetsData(imageFilePath, frames, options) {
    const { width, height, scale = 1, format = DEFAULT_SPRITESHEETS_FORMAT } = options;
    return {
        frames,
        meta: {
            image: imageFilePath,
            format,
            size: { w: width, h: height },
            scale,
        },
    };
}

const TextureOptionsSchema = object({
    scale: optional(number()),
});
const OutputOptionsSchema = object({
    format: union([literal('png'), literal('webp'), literal('avif'), literal('jpg')]),
    width: number(),
    height: number(),
    subDir: optional(string()),
    scale: optional(number()),
    suffix: optional(string()),
    name: optional(string()),
    metaScale: optional(number()),
    background: optional(string()),
});
const SettingsOptionsSchema = object({
    sourceDir: optional(string()),
    targetDir: string(),
    sourceList: array(string()),
    subDir: optional(string()),
    details: optional(record(string(), record(string(), TextureOptionsSchema))),
    output: array(OutputOptionsSchema),
    addTextures: optional(record(string(), array(string()))),
    withoutExtension: optional(boolean()),
});
const ConfigSchema = object({
    settings: array(SettingsOptionsSchema),
    allowRotation: optional(boolean()),
    cache: optional(boolean()),
    cacheName: optional(string()),
});
const AssetCacheSchema = record(string(), optional(array(string())));

async function getJsonFile(filePath, schema) {
    const configFile = await readFile(filePath, { encoding: 'utf-8' });
    const data = globalThis.JSON.parse(configFile);
    return parse(schema, data);
}
function makeTextureFormat(format, factory) {
    switch (format) {
        case 'png': {
            return factory.png();
        }
        case 'webp': {
            return factory.webp();
        }
        case 'avif': {
            return factory.avif();
        }
        case 'jpg': {
            return factory.jpeg();
        }
    }
}
function createBufferFromData(data, format) {
    const stringData = globalThis.JSON.stringify(data, null, format ? 4 : 0);
    return globalThis.Buffer.from(stringData);
}
function getProcessFlagValue(flagName, argsList) {
    const flagIndex = argsList.findIndex((argName) => argName === flagName);
    if (flagIndex === -1)
        return [false];
    const value = argsList[flagIndex + 1];
    if (!value || value.startsWith('-'))
        return [true];
    return [true, value];
}

void (await (async function main() {
    const cwd = process.cwd();
    const [format] = getProcessFlagValue('--format', process.argv);
    const [, configPath = './assets-config.json'] = getProcessFlagValue('--config', process.argv);
    const config = await getJsonFile(path.resolve(cwd, configPath), ConfigSchema);
    const assetCachePath = path.resolve(cwd, config.cacheName ?? DEFAULT_ASSET_CACHE_NAME);
    const assetCache = await (async () => {
        try {
            if (config.cache === false)
                return {};
            return await getJsonFile(assetCachePath, AssetCacheSchema);
        }
        catch {
            return {};
        }
    })();
    const assets = new Assets(cwd);
    const rectPackerOptions = { allowRotation: config.allowRotation == null ? true : !!config.allowRotation };
    const getTextureData = async (src, withoutExtension) => {
        try {
            const stats = await stat(src);
            if (stats.isDirectory())
                return null;
            return await assets.getTextureData(src, withoutExtension);
        }
        catch {
            // TODO: добавить обработку ошибок в случае текстуры
            return null;
        }
    };
    for (const setting of config.settings) {
        const { sourceDir = '', subDir = '', withoutExtension } = setting;
        for (const sourceSrc of setting.sourceList) {
            const detailsOptions = setting.details?.[sourceSrc];
            const addTextures = setting.addTextures?.[sourceSrc] ?? [];
            const sourceDirSrc = path.join(sourceDir, sourceSrc, subDir);
            const sourceDirPath = path.resolve(cwd, sourceDirSrc);
            const animations = new Map();
            const items = await readdir(sourceDirPath);
            const itemPaths = items
                .map((src) => path.join(sourceDirPath, src))
                .concat(addTextures.map((src) => path.resolve(cwd, sourceDir, src)));
            const directoryTextureHashes = assetCache[sourceDirSrc];
            let textureHashes = directoryTextureHashes ? new Set(directoryTextureHashes) : null;
            const textureDataList = await itemPaths.reduce(async (acc, src) => {
                const textureData = await getTextureData(src, withoutExtension);
                if (!textureData)
                    return acc;
                const dataList = await acc;
                if (!textureHashes)
                    return dataList.concat(textureData);
                if (!textureHashes.has(textureData.hash))
                    textureHashes = null;
                textureHashes?.delete(textureData.hash);
                return dataList.concat(textureData);
            }, Promise.resolve([]));
            if (textureHashes && !textureHashes.size)
                continue;
            textureDataList.forEach((textureData) => {
                const chunks = textureData.name.split('_');
                if (chunks[1]) {
                    const animationName = chunks.slice(0, -1).join('_');
                    const animation = animations.get(animationName) ?? [];
                    animation.push(textureData.name);
                    animations.set(animationName, animation);
                }
            });
            animations.forEach((list) => list.sort());
            assetCache[sourceDirSrc] = Array.from(textureDataList.reduce((set, { hash, name }) => {
                if (set.has(hash)) {
                    process.stdin.write(`Хэш файла ${name} совпадает с уже добавленными в спрайт текстурами\n`);
                }
                return set.add(hash);
            }, new Set()));
            for (const options of setting.output) {
                const { metaScale, suffix = '', name = DEFAULT_SPRITESHEETS_NAME, subDir = '', background = '' } = options;
                const maxRectsPacker = new MaxRectsPacker(options.width, options.height, 1, rectPackerOptions);
                const currentTextureData = textureDataList.map(async (textureData) => {
                    const textureOptions = detailsOptions?.[textureData.name];
                    let td = textureData;
                    td = await resizeTexture(td, (options.scale ?? 1) * (textureOptions?.scale ?? 1));
                    td = await trimTexture(td);
                    return td;
                });
                maxRectsPacker.addArray(await Promise.all(currentTextureData));
                const spriteDataPromises = maxRectsPacker.bins.map(async ({ width, height, rects }) => {
                    const textureDataPromises = rects.map(async (textureData) => {
                        if (!textureData.rot)
                            return textureData;
                        return await rotateTexture(textureData);
                    });
                    const textureDataList = await Promise.all(textureDataPromises);
                    return { width, height, textureDataList };
                });
                const spriteDataList = await Promise.all(spriteDataPromises);
                const multiPacks = [];
                const { length } = spriteDataList;
                for (let index = length - 1; index >= 0; index -= 1) {
                    const { width, height, textureDataList } = spriteDataList[index];
                    const key = index && length > 1 ? `${name}-${index}` : name;
                    const spriteFileName = `${key}${suffix}.${options.format}`;
                    const configFileName = `${key}${suffix}${".json" /* Ext.json */}`;
                    const frames = createSpritesheetsFrames(textureDataList);
                    const factory = createSpriteFactory(width, height, { background }).composite(createOverlayOptions(textureDataList));
                    const spriteFactory = makeTextureFormat(options.format, factory);
                    const spriteBuffer = await spriteFactory.toBuffer();
                    const spriteHash = await assets.getFileHash(spriteBuffer);
                    const spriteOptions = { width, height, scale: metaScale };
                    const configFile = createSpritesheetsData(`${spriteFileName}?hash=${spriteHash}`, frames, spriteOptions);
                    if (index)
                        multiPacks.push(configFileName);
                    else {
                        if (multiPacks.length)
                            configFile.meta.related_multi_packs = multiPacks.reverse();
                        animations.forEach((animationList, animationName) => {
                            if (!configFile.animations)
                                configFile.animations = {};
                            configFile.animations[animationName] = animationList;
                        });
                    }
                    const configFileBuffer = createBufferFromData(configFile, format);
                    const targetPath = path.resolve(cwd, setting.targetDir, sourceSrc, subDir);
                    await mkdir(targetPath, { recursive: true });
                    await writeFile(path.join(targetPath, spriteFileName), spriteBuffer);
                    await writeFile(path.join(targetPath, configFileName), configFileBuffer);
                    if (config.cache !== false)
                        await writeFile(assetCachePath, createBufferFromData(assetCache));
                }
            }
        }
    }
})());

